#include "workflow_views.h"
#include <algorithm>
namespace simple_editor::core {
ContextRows BuildContextRows(const std::vector<unsigned char>& important,unsigned context,const std::set<std::size_t>& expanded) {
    ContextRows result; if (important.size() > 600000 || context > 50) return result; std::vector<int> delta(important.size() + 1); for (std::size_t i = 0; i < important.size(); ++i) if (important[i]) { ++delta[i > context ? i - context : 0]; --delta[(std::min)(important.size(),i + context + 1)]; } std::vector<unsigned char> keep(important.size()); int count = 0; for (std::size_t i = 0; i < keep.size(); ++i) { count += delta[i]; keep[i] = count > 0; }
    for (std::size_t i = 0; i < keep.size();) { if (keep[i]) { result.rows.push_back(i++); continue; } const auto begin = i; while (i < keep.size() && !keep[i]) ++i; if (expanded.count(begin)) for (auto n = begin; n < i; ++n) result.rows.push_back(n); else { result.rows.push_back(begin); result.hidden[begin] = i - begin; } } return result;
}
FolderTreeRows BuildFolderTreeRows(const FolderScan& scan,const std::vector<std::size_t>& eligible,const std::set<std::size_t>& expanded) {
    FolderTreeRows result; const auto size = scan.rows.size(); if (size > 200000) return result; result.depth.resize(size); result.differences.resize(size); result.errors.resize(size); const auto none = size; struct Less { bool operator()(const std::wstring& a,const std::wstring& b) const { return CompareStringOrdinal(a.c_str(),-1,b.c_str(),-1,TRUE) == CSTR_LESS_THAN; } }; std::map<std::wstring,std::size_t,Less> paths; for (std::size_t i = 0; i < size; ++i) paths.emplace(scan.rows[i].relative.wstring(),i);
    std::vector<std::size_t> parents(size,none),by_depth; std::vector<std::vector<std::size_t>> children(size + 1); std::vector<unsigned char> included(size); for (std::size_t i = 0; i < size; ++i) { auto parent = scan.rows[i].relative.parent_path(); result.depth[i] = scan.rows[i].relative.empty() ? 0u : static_cast<unsigned>(std::distance(scan.rows[i].relative.begin(),scan.rows[i].relative.end()) - 1); while (!parent.empty()) { const auto found = paths.find(parent.wstring()); if (found != paths.end()) { parents[i] = found->second; break; } parent = parent.parent_path(); } by_depth.push_back(i); const auto& row = scan.rows[i]; result.differences[i] = !row.left.directory && !row.right.directory && ((row.state != FolderState::Equal && row.state != FolderState::Error) || row.text_state == L"Important text differences"); result.errors[i] = row.state == FolderState::Error || row.state == FolderState::TypeConflict || !row.text_error.empty(); }
    std::stable_sort(by_depth.begin(),by_depth.end(),[&](auto a,auto b) { return result.depth[a] > result.depth[b]; }); for (auto i : by_depth) if (parents[i] != none) { result.differences[parents[i]] += result.differences[i]; result.errors[parents[i]] += result.errors[i]; }
    for (auto i : eligible) if (i < size) { auto parent = i; while (parent != none && !included[parent]) { included[parent] = 1; parent = parents[parent]; } }
    std::vector<std::size_t> rank(size,size); for (std::size_t n = 0; n < eligible.size(); ++n) if (eligible[n] < size) rank[eligible[n]] = n; for (std::size_t i = 0; i < size; ++i) if (included[i]) children[parents[i]].push_back(i); for (auto& nodes : children) std::stable_sort(nodes.begin(),nodes.end(),[&](auto a,auto b) { if (rank[a] != rank[b]) return rank[a] < rank[b]; return Less{}(scan.rows[a].relative.wstring(),scan.rows[b].relative.wstring()); });
    std::vector<std::size_t> pending(children[none].rbegin(),children[none].rend()); while (!pending.empty()) { const auto i = pending.back(); pending.pop_back(); result.rows.push_back(i); if (expanded.count(i)) pending.insert(pending.end(),children[i].rbegin(),children[i].rend()); } return result;
}
}
